/**
 * Events to reprice: rated, carrying a snapshot, and whose snapshot
 * references a (still existing) price row whose identity is in $rowIds.
 *
 * @param list<int> $rowIds
 * @return list<array<string, string|int|null>>
 */
public function fetchRepriceEvents(array $rowIds): array
{
    if ($rowIds === []) {
        return [];
    }
    $in = implode(',', array_map(static fn (int $id): string => (string) $id, $rowIds));

    return $this->fetchAll(
        'SELECT e.*
         FROM "billing_usage_events" e
         WHERE e."state" = ?
           AND e."rate_spec_json" IS NOT NULL
           AND e."rate_row_id" IN ('.$in.')
         ORDER BY e."id" ASC'
        ,
        array_values([self::STATE_RATED]),
    );
}

