        foreach ($result->errors as $err) {
            $stderr->writeln($err);
        }

        $exitCode = $result->errors !== [] ? Command::FAILURE : Command::SUCCESS;

        $output->writeln(sprintf('IMPORTED_EVENTS=%d', $result->usageEvents));

        return $exitCode;
    }
