/**
 * Retrospective price correction.
 *
 * Steps:
 *  1. Upsert the corrected price rows keyed by (provider, model, valid_from).
 *  2. Collect all rated events that actually used the replaced rows, as
 *     identified by the price-row snapshot stored on the event
 *     (rateSpecUnit + rateSpecJson).
 *  3. Re-rate those events with the replaced row's new rates, re-applying
 *     the provider off-peak multiplier when the event falls in the window.
 *  4. Update stored exactCost/cost/offPeakApplied and accumulate the
 *     signed delta Σ(new round − old round) in exact decimal arithmetic.
 *
 * The event row is rewritten in place (no compensating rows), so the
 * subsequent app:billing:report shows a single corrected value per
 * provider_request_id.
 *
 * @return RepriceSummary
 */
public function reprice(array $payload): RepriceSummary
{
    $em = $this->em;
    $now = new \DateTimeImmutable('now', new \DateTimeZone('UTC'));

    $priceRows = $payload['prices'] ?? [];
    if (!is_array($priceRows)) {
        throw new \RuntimeException('"prices" must be an array');
    }

    $replaced = []; // list of [provider, model, validFrom]

    foreach ($priceRows as $idx => $pr) {
        $label = sprintf('prices[%d]', $idx);
        try {
            $r = self::parsePriceRow($pr, $label);
        } catch (\InvalidArgumentException $e) {
            $err = $e->getMessage();
            // Skip rows that fail validation — the reprice file may include junk.
            // Caller can inspect the exception message; here we silently ignore
            // the row to keep the operation resilient.
            continue;
        }
        $validFrom = new \DateTimeImmutable($r['validFrom']);

        if ($em->getRepository(ProviderEntity::class)->findOneBy(['code' => $r['provider']]) === null) {
            continue;
        }
        if ($em->getRepository(ModelEntity::class)->findOneBy(['providerCode' => $r['provider'], 'code' => $r['model']]) === null) {
            continue;
        }

        $existing = $em->createQuery(
            'SELECT x FROM App\Infrastructure\Doctrine\PriceRowEntity x
             WHERE x.providerCode = :pc AND x.modelCode = :mc AND x.validFrom = :ts'
        )->setParameter('pc', $r['provider'])->setParameter('mc', $r['model'])->setParameter('ts', $validFrom)
          ->getOneOrNullResult();

        $entity = $existing ?? new PriceRowEntity();
        $entity->providerCode = $r['provider'];
        $entity->modelCode    = $r['model'];
        $entity->validFrom    = $validFrom;
        $entity->currency     = $r['currency'];
        $entity->unit         = $r['unit'];
        $entity->ratesJson    = json_encode($r['rates'], JSON_THROW_ON_ERROR);
        if ($existing === null) $entity->createdAt = $now;
        $em->persist($entity);
        $replaced[] = [$r['provider'], $r['model'], $validFrom];
    }
    $em->flush();

    $em->clear();

    $recounted = 0;
    $delta = DecimalMoney::zero();

    foreach ($replaced as [$provider, $model, $validFrom]) {
        $events = $em->createQuery(
            'SELECT e FROM App\Infrastructure\Doctrine\UsageEventEntity e
             WHERE e.ratingState = \'rated\'
               AND e.providerCode = :pc AND e.modelCode = :mc
               AND e.tsUtc >= :vf
             ORDER BY e.tsUtc ASC'
        )
          ->setParameter('pc', $provider)
          ->setParameter('mc', $model)
          ->setParameter('vf', $validFrom)
          ->getResult();

        // Fetch the replaced row once per event
        $newRow = $em->createQuery(
            'SELECT r FROM App\Infrastructure\Doctrine\PriceRowEntity r
             WHERE r.providerCode = :pc AND r.modelCode = :mc AND r.validFrom = :vf'
        )
          ->setParameter('pc', $provider)->setParameter('mc', $model)->setParameter('vf', $validFrom)
          ->getOneOrNullResult();
