        // Verify the new in-force row is still this one for the event's ts
        // (i.e., no more-recent row supersedes it at the event's timestamp).
        $providerRow = $em->getRepository(ProviderEntity::class)->findOneBy(['code' => $provider]);

        foreach ($events as $e) {
            // Re-compute the most recent in-force row at the event's ts.
            // Only re-rate if it is the replaced row (valid_from matches exactly).
            $inForceRow = $em->createQuery(
                'SELECT r FROM App\Infrastructure\Doctrine\PriceRowEntity r
                 WHERE r.providerCode = :pc AND r.modelCode = :mc AND r.validFrom <= :ts
