                continue;
            }

            $oldRounded = $e->cost !== null ? DecimalMoney::fromDecimalString($e->cost) : DecimalMoney::zero();
            $rateSpec   = json_decode($inForceRow->ratesJson, true, 512, JSON_THROW_ON_ERROR) ?: [];
            $tok        = new TokenUsage($e->tokensInput, $e->tokensOutput, $e->tokensCacheRead, $e->tokensCacheWrite);
            $newCost    = self::exactCost($inForceRow->unit, $rateSpec, $tok);

            $offAppl = false;
            if ($providerRow !== null
                && $providerRow->offPeakStartMin !== null
                && $providerRow->offPeakEndMin   !== null
                && $providerRow->offPeakMultiplier !== null) {
                $w = new OffPeakWindow(
                    $providerRow->offPeakStartMin,
                    $providerRow->offPeakEndMin,
                    $providerRow->offPeakMultiplier,
                );
                $utcMin = (int)$e->tsUtc->format('G') * 60 + (int)$e->tsUtc->format('i');
                if ($w->inWindow($utcMin)) {
                    $newCost = $newCost->multiply(DecimalMoney::fromDecimalString($providerRow->offPeakMultiplier));
                    $offAppl = true;
                }
            }
            $newRounded = $newCost->roundTo(DecimalMoney::ROUND_SCALE);

            $delta = $delta->add($newRounded->subtract($oldRounded));

            $e->exactCost      = $newCost->toBcString();
            $e->cost           = $newRounded->toBcString();
            $e->rateSpecUnit   = $inForceRow->unit;
            $e->rateSpecJson   = $inForceRow->ratesJson;
            $e->offPeakApplied = $offAppl;
            $e->updatedAt      = $now;
            $recounted++;
        }
    }
    $em->flush();

    return new RepriceSummary($recounted, $delta);
}

